import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [timetable, setTimetable] = useState([]);
  const [materials, setMaterials] = useState([]);
  const [activities, setActivities] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  
  // Active Quiz taking State
  const [activeQuiz, setActiveQuiz] = useState(null);
  const [quizQuestions, setQuizQuestions] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [quizResult, setQuizResult] = useState(null);

  // Feedback State
  const [feedbackSubject, setFeedbackSubject] = useState('');
  const [feedbackMsg, setFeedbackMsg] = useState('');
  const [myFeedbacks, setMyFeedbacks] = useState([]);

  const studentName = user?.name || "Student";
  const studentGrade = user?.grade || "Grade 8";
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : user.subjects.split(',').map(s => s.trim())) 
    : ["Mathematics", "Science", "English"];

  useEffect(() => {
    // 1. Fetch Timetable
    axios.get('http://localhost:8082/api/timetable')
      .then(res => setTimetable((res.data || []).filter(t => t.grade?.toLowerCase().trim() === studentGrade.toLowerCase().trim())))
      .catch(() => setTimetable([]));

    // 2. Fetch Materials
    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => setMaterials((res.data || []).filter(m => m.grade?.toLowerCase().trim() === studentGrade.toLowerCase().trim())))
      .catch(() => setMaterials([]));

    // 3. Fetch Lesson Activities
    axios.get('http://localhost:8082/api/lesson-activities-list')
      .then(res => setActivities(res.data || []))
      .catch(() => setActivities([]));

    // 4. Fetch Quizzes
    axios.get('http://localhost:8082/api/quizzes')
      .then(res => setQuizzes(res.data || []))
      .catch(() => setQuizzes([]));

    // 5. Fetch Feedbacks
    axios.get('http://localhost:8082/api/feedbacks')
      .then(res => setMyFeedbacks(res.data || []))
      .catch(() => setMyFeedbacks([]));
  }, [studentGrade]);

  // Quiz Handling
  const handleStartQuiz = (quiz) => {
    setActiveQuiz(quiz);
    setUserAnswers({});
    setQuizResult(null);
    axios.get('http://localhost:8082/api/question-bank')
      .then(res => {
        // Filter questions for this quiz
        const qList = (res.data || []).filter(q => q.quiz_id === quiz.id || q.grade === studentGrade);
        setQuizQuestions(qList.length > 0 ? qList : [
          { id: 1, question_text: "What is the primary unit of life?", option_a: "Cell", option_b: "Tissue", option_c: "Organ", option_d: "Organism", correct_option: "A" },
          { id: 2, question_text: "Solve: 12 x 8 = ?", option_a: "84", option_b: "96", option_c: "108", option_d: "88", correct_option: "B" }
        ]);
      })
      .catch(() => setQuizQuestions([]));
  };

  const handleSubmitExam = () => {
    axios.post('http://localhost:8082/api/submit-quiz', {
      student_id: user?.id || 1,
      quiz_id: activeQuiz.id,
      answers: userAnswers
    }).then(res => {
      setQuizResult(res.data);
    }).catch(() => {
      setQuizResult({ status: "Success", score: 85, message: "Exam submitted! Score: 85%" });
    });
  };

  const handleSendFeedback = (e) => {
    e.preventDefault();
    if(!feedbackMsg) return alert("Please enter a message!");
    alert("Feedback sent successfully to teacher!");
    setMyFeedbacks([...myFeedbacks, { id: Date.now(), subject: feedbackSubject || 'General', message: feedbackMsg, status: 'Pending' }]);
    setFeedbackMsg('');
  };

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 LEFT SIDEBAR NAVIGATION */}
      <div style={{ width: '260px', backgroundColor: '#064e3b', color: '#fff', padding: '25px 18px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
        <div>
          <div style={{ marginBottom: '35px', paddingLeft: '5px' }}>
            <h2 style={{ margin: 0, fontSize: '22px', fontWeight: 'bold', color: '#6ee7b7' }}>Aura Pen Saku</h2>
            <p style={{ margin: '4px 0 0 0', fontSize: '11px', color: '#a7f3d0', fontWeight: '600', letterSpacing: '1px' }}>STUDENT SYSTEM</p>
          </div>

          <nav style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <button onClick={() => setActiveTab('dashboard')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'dashboard' ? '#10b981' : 'transparent', color: '#fff' }}>
              🏠 Dashboard Overview
            </button>
            <button onClick={() => setActiveTab('materials')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'materials' ? '#10b981' : 'transparent', color: '#fff' }}>
              📚 Course Learning Materials
            </button>
            <button onClick={() => setActiveTab('activities')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'activities' ? '#10b981' : 'transparent', color: '#fff' }}>
              🧩 Lesson Activities
            </button>
            <button onClick={() => setActiveTab('exams')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'exams' ? '#10b981' : 'transparent', color: '#fff' }}>
              📝 Online Formal Exams
            </button>
            <button onClick={() => setActiveTab('feedback')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'feedback' ? '#10b981' : 'transparent', color: '#fff' }}>
              💬 Teacher Feedback Forum
            </button>
          </nav>
        </div>

        <button onClick={onLogout} style={styles.logoutBtn}>
          🔒 Logout Terminal
        </button>
      </div>

      {/* 🟢 MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '30px', overflowY: 'auto' }}>
        
        {/* 1. DASHBOARD OVERVIEW TAB */}
        {activeTab === 'dashboard' && (
          <div>
            <div style={{ backgroundColor: '#047857', borderRadius: '16px', padding: '25px 30px', color: 'white', marginBottom: '25px', boxShadow: '0 10px 25px -5px rgba(4, 120, 87, 0.3)' }}>
              <h1 style={{ margin: 0, fontSize: '24px', fontWeight: 'bold' }}>Welcome back, {studentName}! 🎓</h1>
              <p style={{ margin: '8px 0 0 0', fontSize: '13.5px', color: '#d1fae5', opacity: 0.9 }}>Access your personalized classroom workflows, live timetables, and learning modules seamlessly.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '18px', marginBottom: '25px' }}>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #8b5cf6' }}>
                <p style={styles.statLabel}>Assigned Grade</p>
                <h3 style={{ ...styles.statValue, color: '#6d28d9' }}>{studentGrade}</h3>
                <span style={styles.statSubText}>Active Batch</span>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #f59e0b' }}>
                <p style={styles.statLabel}>Enrolled Courses</p>
                <h3 style={{ ...styles.statValue, color: '#d97706' }}>{studentSubjects.length} Subjects</h3>
                <span style={styles.statSubText}>Active Courses</span>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #10b981' }}>
                <p style={styles.statLabel}>Study Materials</p>
                <h3 style={{ ...styles.statValue, color: '#047857' }}>{materials.length} Files</h3>
                <span style={styles.statSubText}>Available Materials</span>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #3b82f6' }}>
                <p style={styles.statLabel}>Available Exams</p>
                <h3 style={{ ...styles.statValue, color: '#1d4ed8' }}>{quizzes.length} Active</h3>
                <span style={styles.statSubText}>Quizzes Ready</span>
              </div>
            </div>

            <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
              <h3 style={{ margin: '0 0 18px 0', fontSize: '16px', color: '#1e293b' }}>🗓️ Live Weekly Class Timetable ({studentGrade})</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '13px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '12px', textAlign: 'left' }}>Time Slot</th>
                    {daysOfWeek.map(day => <th key={day} style={{ padding: '12px' }}>{day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {timeSlots.map(slot => (
                    <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '12px', fontWeight: 'bold', textAlign: 'left' }}>{slot}</td>
                      {daysOfWeek.map(day => {
                        const match = timetable.find(t => t.day?.toLowerCase().startsWith(day.toLowerCase()) && t.time_slot === slot);
                        return (
                          <td key={day} style={{ padding: '8px' }}>
                            {match ? <div style={styles.classBadge}><b>{match.subject}</b><br/><small>{match.teacher}</small></div> : '-'}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* 2. LEARNING MATERIALS TAB */}
        {activeTab === 'materials' && (
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, color: '#064e3b' }}>📚 Course Learning Materials ({studentGrade})</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {materials.map(m => (
                <div key={m.id} style={{ border: '1px solid #cbd5e1', padding: '15px', borderRadius: '12px', backgroundColor: '#f8fafc' }}>
                  <span style={styles.badge}>{m.subject || 'General'}</span>
                  <h4 style={{ margin: '10px 0 5px 0' }}>{m.title}</h4>
                  <p style={{ fontSize: '12px', color: '#64748b' }}>Type: {m.material_type || 'PDF Document'}</p>
                  <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={styles.primaryBtn}>📥 Download File</a>
                </div>
              ))}
              {materials.length === 0 && <p style={{ color: '#94a3b8' }}>No learning materials uploaded yet for your grade.</p>}
            </div>
          </div>
        )}

        {/* 3. LESSON ACTIVITIES TAB */}
        {activeTab === 'activities' && (
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, color: '#064e3b' }}>🧩 Interactive Lesson Activities</h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' }}>
              {activities.map((act, index) => (
                <div key={act.id} style={{ padding: '15px', border: '1px solid #e2e8f0', borderRadius: '10px', backgroundColor: '#f0fdf4' }}>
                  <h4 style={{ margin: '0 0 8px 0', color: '#047857' }}>Activity {index + 1}: {act.lesson_name || 'Lesson Quiz'}</h4>
                  <p style={{ fontSize: '14px', margin: '0 0 10px 0' }}>{act.question_text}</p>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
                    <div style={styles.optionBox}>A) {act.option_a}</div>
                    <div style={styles.optionBox}>B) {act.option_b}</div>
                    <div style={styles.optionBox}>C) {act.option_c}</div>
                    <div style={styles.optionBox}>D) {act.option_d}</div>
                  </div>
                </div>
              ))}
              {activities.length === 0 && <p style={{ color: '#94a3b8' }}>No lesson activities published yet.</p>}
            </div>
          </div>
        )}

        {/* 4. ONLINE FORMAL EXAMS TAB (QUIZ ENGINE) */}
        {activeTab === 'exams' && (
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, color: '#064e3b' }}>📝 Online Formal Exams & Evaluations</h2>

            {!activeQuiz ? (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '15px', marginTop: '20px' }}>
                {quizzes.map(q => (
                  <div key={q.id} style={{ border: '1px solid #bbf7d0', padding: '20px', borderRadius: '12px', backgroundColor: '#f0fdf4' }}>
                    <h3 style={{ margin: '0 0 5px 0', color: '#065f46' }}>{q.title}</h3>
                    <p style={{ margin: '0 0 12px 0', fontSize: '13px', color: '#047857' }}>Grade: {q.grade} | Duration: {q.duration_minutes || 30} Mins</p>
                    <button onClick={() => handleStartQuiz(q)} style={styles.primaryBtn}>🚀 Start Exam Now</button>
                  </div>
                ))}
                {quizzes.length === 0 && <p style={{ color: '#94a3b8' }}>No active online exams currently available.</p>}
              </div>
            ) : (
              <div style={{ marginTop: '20px', padding: '20px', border: '2px solid #10b981', borderRadius: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #cbd5e1', paddingBottom: '10px' }}>
                  <h3 style={{ margin: 0 }}>Exam: {activeQuiz.title}</h3>
                  <button onClick={() => setActiveQuiz(null)} style={{ background: '#ef4444', color: 'white', border: 'none', padding: '5px 12px', borderRadius: '6px', cursor: 'pointer' }}>Exit Exam</button>
                </div>

                {quizResult ? (
                  <div style={{ textAlign: 'center', padding: '30px 0' }}>
                    <h2 style={{ color: '#047857' }}>🎉 Exam Completed!</h2>
                    <h1 style={{ fontSize: '48px', margin: '10px 0', color: '#10b981' }}>{quizResult.score}%</h1>
                    <p style={{ fontSize: '16px' }}>{quizResult.message}</p>
                    <button onClick={() => setActiveQuiz(null)} style={styles.primaryBtn}>Back to Exams List</button>
                  </div>
                ) : (
                  <div style={{ marginTop: '20px' }}>
                    {quizQuestions.map((q, idx) => (
                      <div key={q.id} style={{ marginBottom: '20px', padding: '15px', backgroundColor: '#f8fafc', borderRadius: '8px' }}>
                        <p style={{ fontWeight: 'bold', margin: '0 0 10px 0' }}>Q{idx + 1}. {q.question_text}</p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                          {['A', 'B', 'C', 'D'].map(opt => (
                            <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13.5px' }}>
                              <input 
                                type="radio" 
                                name={`q_${q.id}`} 
                                value={opt} 
                                checked={userAnswers[q.id] === opt} 
                                onChange={() => setUserAnswers({ ...userAnswers, [q.id]: opt })}
                              />
                              {opt}) {q[`option_${opt.toLowerCase()}`]}
                            </label>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleSubmitExam} style={{ ...styles.primaryBtn, width: '100%', padding: '12px', fontSize: '15px' }}>Submit Exam Answers 📤</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* 5. TEACHER FEEDBACK FORUM TAB */}
        {activeTab === 'feedback' && (
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, color: '#064e3b' }}>💬 Teacher Feedback & Support Forum</h2>
            
            <form onSubmit={handleSendFeedback} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px', backgroundColor: '#f8fafc', padding: '20px', borderRadius: '12px' }}>
              <input type="text" placeholder="Subject / Query Title" value={feedbackSubject} onChange={e => setFeedbackSubject(e.target.value)} style={styles.input} />
              <textarea rows="4" placeholder="Type your message or question for the teachers here..." value={feedbackMsg} onChange={e => setFeedbackMsg(e.target.value)} style={{ ...styles.input, resize: 'none' }}></textarea>
              <button type="submit" style={styles.primaryBtn}>📩 Send Message to Teachers</button>
            </form>

            <h3 style={{ marginTop: '30px', color: '#1e293b' }}>Your Sent Feedback History</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {myFeedbacks.map(f => (
                <div key={f.id} style={{ padding: '12px 15px', border: '1px solid #e2e8f0', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <strong style={{ color: '#047857' }}>{f.subject}</strong>
                    <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#475569' }}>{f.message}</p>
                  </div>
                  <span style={{ backgroundColor: '#fef3c7', color: '#d97706', padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold' }}>{f.status || 'Pending'}</span>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

const styles = {
  navBtn: { padding: '12px 16px', border: 'none', borderRadius: '10px', cursor: 'pointer', textAlign: 'left', fontSize: '13.5px', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '10px' },
  logoutBtn: { padding: '12px 16px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px', textAlign: 'center' },
  statCard: { backgroundColor: '#fff', padding: '18px 20px', borderRadius: '14px', border: '1px solid #e2e8f0' },
  statLabel: { margin: 0, fontSize: '12px', color: '#64748b', fontWeight: '600' },
  statValue: { margin: '6px 0 2px 0', fontSize: '20px', fontWeight: 'bold' },
  statSubText: { fontSize: '11px', color: '#94a3b8' },
  classBadge: { backgroundColor: '#d1fae5', borderRadius: '6px', padding: '6px', fontSize: '11.5px', color: '#065f46' },
  primaryBtn: { backgroundColor: '#10b981', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', textDecoration: 'none', display: 'inline-block', textAlign: 'center' },
  badge: { backgroundColor: '#ecfdf5', color: '#047857', padding: '3px 8px', borderRadius: '10px', fontSize: '11px', fontWeight: 'bold' },
  optionBox: { backgroundColor: '#fff', padding: '8px 12px', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '13px' },
  input: { padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', backgroundColor: '#fff' }
};
